import type { ImageMetadata } from 'astro';
import type { Locale } from '@/i18n/routes';

/**
 * Image registry. Every image on the site is a named slot.
 *
 * To swap an image: drop the new file into src/assets/img/, point `file` at it and set `source`.
 *   placeholder – generated by scripts/generate-placeholders.mjs (layout only)
 *   ai          – AI-generated illustration (mood only, never presented as our work)
 *   stock       – licensed stock (credit + license required)
 *   client      – real Paintfix photo (the only source allowed for "our work" contexts)
 */
export type MediaSource = 'placeholder' | 'ai' | 'stock' | 'client';

interface Slot {
  file: string;
  source: MediaSource;
  alt: Record<Locale, string>;
  credit?: string;
  license?: string;
}

const files = import.meta.glob<{ default: ImageMetadata }>(
  '/src/assets/img/**/*.{webp,png,jpg,jpeg,avif}',
  {
    eager: true,
  },
);

