export type SlotId = keyof typeof slots;

export interface ResolvedMedia extends Slot {
  id: SlotId;
  src: ImageMetadata;
}

export function media(id: SlotId): ResolvedMedia {
  const slot: Slot = slots[id];
  const mod = files[`/src/assets/img/${slot.file}`];
  if (!mod)
    throw new Error(`media: file "${slot.file}" for slot "${id}" not found in src/assets/img`);
  return { ...slot, id, src: mod.default };
}

/**
 * Guardrail: "our work" contexts (before/after, references) only accept real client photos.
 * AI and stock images are mood only (UWG § 5).
 */
export function clientMedia(id: SlotId): ResolvedMedia {
  const m = media(id);
  if (m.source !== 'client') {
    throw new Error(
      `media: slot "${id}" is "${m.source}" but this context requires a real client photo`,
    );
  }
  return m;
}

/** Credits for the Impressum (stock licences and AI illustrations). */
export function imageCredits() {
  return (Object.keys(slots) as SlotId[])
    .map((id) => media(id))
    .filter((m) => m.source === 'stock' || m.source === 'ai');
}

export const hasPlaceholders = (Object.values(slots) as Slot[]).some(
  (s) => s.source === 'placeholder',
);
